<?php
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/unified_experience_v1100.php';require_once __DIR__.'/app/local_assistant_booking_v1040.php';$me=current_user();if(!$me){header('Location: /login.php?next='.rawurlencode('/booking-inbox-v1040.php'));exit;}$uid=(int)$me['id'];$flash='';$error='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$a=(string)($_POST['action']??'');if($a==='status'){sk1040_provider_update($uid,(int)($_POST['id']??0),(string)($_POST['status']??''),(string)($_POST['note']??''),(string)($_POST['new_date']??''),(string)($_POST['new_time']??''));$flash='Booking updated.';}elseif($a==='availability'){sk1040_save_availability($uid,$_POST);$flash='Availability saved.';}elseif($a==='availability_delete'){sk1040_delete_availability($uid,(int)($_POST['id']??0));$flash='Availability removed.';}}}catch(Throwable $e){$error=$e->getMessage();}$rows=sk1040_provider_bookings($uid);$entities=sk1040_provider_entities($uid);$availability=sk1040_availability($uid);$csrf=csrf_token();$days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Booking Inbox — ShahkotPK</title><link rel="stylesheet" href="/assets/local-assistant-v1040.css?v=1040"><?php sk1100_public_assets();?></head><body><?php sk1100_render_public_header(true);?><header class="la-top"><div class="la-shell"><a class="brand" href="/assistant-v1040.php">← Ask ShahkotPK</a><nav><a href="/service-leads-v1030.php">Business Leads</a><a href="/my-bookings-v1040.php">My Bookings</a></nav></div></header><main><section class="la-hero compact"><div class="la-shell"><span>PROVIDER BOOKING INBOX</span><h1>Manage customer booking requests</h1><p>Confirm, request another time, complete or reject bookings routed to your owned business/provider profile.</p></div></section><section class="la-section"><div class="la-shell"><?php if($flash):?><div class="notice ok"><?=sk1040_h($flash)?></div><?php endif;?><?php if($error):?><div class="notice bad"><?=sk1040_h($error)?></div><?php endif;?><div class="booking-list provider"><?php foreach($rows as $r):?><article><div><small><?=sk1040_h((string)$r['booking_no'])?> · <?=sk1040_h(strtoupper((string)$r['entity_type']))?></small><h2><?=sk1040_h((string)$r['entity_title'])?></h2><p><b><?=sk1040_h((string)$r['customer_name'])?></b> · <a href="tel:<?=sk1040_h(preg_replace('/[^0-9+]/','',(string)$r['customer_phone']))?>"><?=sk1040_h((string)$r['customer_phone'])?></a></p><p><?=sk1040_h(date('d M Y h:i A',strtotime((string)$r['requested_at'])))?> · <?=max(1,(int)$r['party_size'])?> person(s)</p><?php if($r['notes']):?><p><?=sk1040_h((string)$r['notes'])?></p><?php endif;?></div><form method="post" class="provider-action"><input type="hidden" name="_csrf" value="<?=sk1040_h($csrf)?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><label>Status<select name="status"><?php foreach(['confirmed','reschedule_requested','completed','rejected','cancelled'] as $st):?><option value="<?=$st?>" <?=$st===$r['status']?'selected':''?>><?=ucwords(str_replace('_',' ',$st))?></option><?php endforeach;?></select></label><label>New date (for reschedule)<input type="date" name="new_date"></label><label>New time<input type="time" name="new_time"></label><label class="wide">Message<input name="note" value="<?=sk1040_h((string)($r['provider_note']??''))?>" placeholder="Confirmation or reschedule message"></label><button class="wide">Update Booking</button></form></article><?php endforeach;?><?php if(!$rows):?><div class="empty"><p>No booking requests are assigned to your provider profile yet.</p></div><?php endif;?></div></div></section><section class="la-section alt"><div class="la-shell"><h2>Weekly availability</h2><p class="muted">Optional availability helps organize your working hours. Customers can still request a time; you confirm the final booking.</p><?php if($entities):?><form method="post" class="availability-form"><input type="hidden" name="_csrf" value="<?=sk1040_h($csrf)?>"><input type="hidden" name="action" value="availability"><label>Provider<select data-entity-select><?php foreach($entities as $e):?><option value="<?=sk1040_h($e['type'].':'.$e['id'])?>"><?=sk1040_h(ucfirst($e['type']).' · '.$e['title'])?></option><?php endforeach;?></select></label><input type="hidden" name="entity_type" data-entity-type value="<?=sk1040_h((string)$entities[0]['type'])?>"><input type="hidden" name="entity_id" data-entity-id value="<?=(int)$entities[0]['id']?>"><label>Day<select name="day_of_week"><?php foreach($days as $i=>$d):?><option value="<?=$i?>"><?=sk1040_h($d)?></option><?php endforeach;?></select></label><label>From<input type="time" name="start_time" value="09:00"></label><label>To<input type="time" name="end_time" value="17:00"></label><label>Slot minutes<input type="number" name="slot_minutes" min="10" max="240" value="30"></label><button>Save Availability</button></form><?php endif;?><div class="availability-list"><?php foreach($availability as $a):?><div><span><b><?=sk1040_h(ucfirst((string)$a['entity_type']))?> #<?=(int)$a['entity_id']?> · <?=sk1040_h($days[(int)$a['day_of_week']]??'Day')?></b> <?=sk1040_h(substr((string)$a['start_time'],0,5))?>–<?=sk1040_h(substr((string)$a['end_time'],0,5))?> · <?=(int)$a['slot_minutes']?> min</span><form method="post"><input type="hidden" name="_csrf" value="<?=sk1040_h($csrf)?>"><input type="hidden" name="action" value="availability_delete"><input type="hidden" name="id" value="<?=(int)$a['id']?>"><button class="link danger">Remove</button></form></div><?php endforeach;?></div></div></section></main><script>document.querySelector('[data-entity-select]')?.addEventListener('change',e=>{const [t,id]=e.target.value.split(':');document.querySelector('[data-entity-type]').value=t;document.querySelector('[data-entity-id]').value=id;});</script><?php sk1100_render_ai_widget('public');?> </body></html>
